-- Cash flow · direct method at voucher level + non-cash transactions (IAS 7.43)
-- Run each with branch='ALL' (the four databases = one company; shared bank accounts). {D1} = day after the cut-off (e.g. 2026-09-29).
-- Cash & equivalents = 121% (boxes, custody) + 122% (banks, card network, visa); overdraft included.
-- Allocation: a voucher's net cash = sum(DR-CR) on its 121/122 lines. Financing lines (loans 2112/2113/2125, 1262000, 3290001,
--   dividends 2128, equity 221/222/223) take their full amount; the rest of the cash goes pro rata to the other lines on the
--   opposite side of that remaining cash. Cash-only vouchers (transfers) net to zero. VOUCHER_NO is unique and every cash voucher balances.
-- Outputs are parsed by dmv/build_cfd.py (r_alloc2.json, r_cash.json, r_ins.json, ncv.json, mixed.json, vch.json, desc.json).

-- 1) r_alloc2 — allocation by counter account x month
SELECT a, COUNT(*) n, LISTAGG(ym||':'||amt||':'||nv, ';') WITHIN GROUP (ORDER BY ym) r FROM (SELECT a, ym, ROUND(SUM(alloc),2) amt, COUNT(DISTINCT v) nv FROM (SELECT l.VOUCHER_NO v, l.ACCOUNT_NO a, l.ym, CASE WHEN l.f=1 THEN -l.net WHEN (x.c-l.fin)<0 AND l.net>0 AND l.pos>0 THEN (x.c-l.fin)*l.net/l.pos WHEN (x.c-l.fin)>0 AND l.net<0 AND l.neg<0 THEN (x.c-l.fin)*l.net/l.neg ELSE 0 END alloc FROM (SELECT d.VOUCHER_NO, d.ACCOUNT_NO, TO_CHAR(MIN(d.VM_DATE),'YYYYMM') ym, CASE WHEN (d.ACCOUNT_NO LIKE '2112%' OR d.ACCOUNT_NO LIKE '2113%' OR d.ACCOUNT_NO LIKE '2125%' OR d.ACCOUNT_NO LIKE '2128%' OR d.ACCOUNT_NO LIKE '221%' OR d.ACCOUNT_NO LIKE '222%' OR d.ACCOUNT_NO LIKE '223%' OR d.ACCOUNT_NO IN ('1262000','3290001')) THEN 1 ELSE 0 END f, SUM(d.DR_AMOUNT-d.CR_AMOUNT) net, SUM(CASE WHEN (d.ACCOUNT_NO LIKE '2112%' OR d.ACCOUNT_NO LIKE '2113%' OR d.ACCOUNT_NO LIKE '2125%' OR d.ACCOUNT_NO LIKE '2128%' OR d.ACCOUNT_NO LIKE '221%' OR d.ACCOUNT_NO LIKE '222%' OR d.ACCOUNT_NO LIKE '223%' OR d.ACCOUNT_NO IN ('1262000','3290001')) THEN -SUM(d.DR_AMOUNT-d.CR_AMOUNT) ELSE 0 END) OVER (PARTITION BY d.VOUCHER_NO) fin, SUM(CASE WHEN NOT (d.ACCOUNT_NO LIKE '2112%' OR d.ACCOUNT_NO LIKE '2113%' OR d.ACCOUNT_NO LIKE '2125%' OR d.ACCOUNT_NO LIKE '2128%' OR d.ACCOUNT_NO LIKE '221%' OR d.ACCOUNT_NO LIKE '222%' OR d.ACCOUNT_NO LIKE '223%' OR d.ACCOUNT_NO IN ('1262000','3290001')) AND SUM(d.DR_AMOUNT-d.CR_AMOUNT)>0 THEN SUM(d.DR_AMOUNT-d.CR_AMOUNT) ELSE 0 END) OVER (PARTITION BY d.VOUCHER_NO) pos, SUM(CASE WHEN NOT (d.ACCOUNT_NO LIKE '2112%' OR d.ACCOUNT_NO LIKE '2113%' OR d.ACCOUNT_NO LIKE '2125%' OR d.ACCOUNT_NO LIKE '2128%' OR d.ACCOUNT_NO LIKE '221%' OR d.ACCOUNT_NO LIKE '222%' OR d.ACCOUNT_NO LIKE '223%' OR d.ACCOUNT_NO IN ('1262000','3290001')) AND SUM(d.DR_AMOUNT-d.CR_AMOUNT)<0 THEN SUM(d.DR_AMOUNT-d.CR_AMOUNT) ELSE 0 END) OVER (PARTITION BY d.VOUCHER_NO) neg FROM GL_TRANSACTIONS_DETAILS d WHERE d.STATUS<>'C' AND d.VM_DATE<DATE '{D1}' AND d.ACCOUNT_NO NOT LIKE '121%' AND d.ACCOUNT_NO NOT LIKE '122%' AND d.VOUCHER_NO IN (SELECT c.VOUCHER_NO FROM GL_TRANSACTIONS_DETAILS c WHERE c.STATUS<>'C' AND (c.ACCOUNT_NO LIKE '121%' OR c.ACCOUNT_NO LIKE '122%')) GROUP BY d.VOUCHER_NO, d.ACCOUNT_NO) l JOIN (SELECT c.VOUCHER_NO, SUM(c.DR_AMOUNT-c.CR_AMOUNT) c FROM GL_TRANSACTIONS_DETAILS c WHERE c.STATUS<>'C' AND c.VM_DATE<DATE '{D1}' AND (c.ACCOUNT_NO LIKE '121%' OR c.ACCOUNT_NO LIKE '122%') GROUP BY c.VOUCHER_NO) x ON x.VOUCHER_NO=l.VOUCHER_NO) GROUP BY a, ym HAVING ABS(SUM(alloc))>=0.005) GROUP BY a;

-- 2) r_cash — cash-account movement by account x month (balance proofs)
SELECT c.ACCOUNT_NO a, LISTAGG(ym||':'||amt, ';') WITHIN GROUP (ORDER BY ym) r FROM (SELECT c.ACCOUNT_NO, TO_CHAR(c.VM_DATE,'YYYYMM') ym, ROUND(SUM(c.DR_AMOUNT-c.CR_AMOUNT),2) amt FROM GL_TRANSACTIONS_DETAILS c WHERE c.STATUS<>'C' AND c.VM_DATE<DATE '{D1}' AND (c.ACCOUNT_NO LIKE '121%' OR c.ACCOUNT_NO LIKE '122%') GROUP BY c.ACCOUNT_NO, TO_CHAR(c.VM_DATE,'YYYYMM')) c GROUP BY c.ACCOUNT_NO;

-- 3) r_ins — receivable accounts 1240% by sub-account (insurers = 1240007) x month  [pro-rata rule; add the {D1} cut-off]
SELECT a, sub, MAX(snm) snm, LISTAGG(ym||':'||amt||':'||nv, ';') WITHIN GROUP (ORDER BY ym) r FROM (SELECT a, sub, MAX(snm) snm, ym, ROUND(SUM(alloc),2) amt, COUNT(DISTINCT v) nv FROM (SELECT l.VOUCHER_NO v, l.ACCOUNT_NO a, l.sub, l.snm, l.net, x.c, l.ym, CASE WHEN x.c<0 AND l.net>0 THEN x.c*l.net/l.pos WHEN x.c>0 AND l.net<0 THEN x.c*l.net/l.neg ELSE 0 END alloc FROM (SELECT d.VOUCHER_NO, d.ACCOUNT_NO, NVL(d.SUB_ACCOUNT_NO,'-') sub, MAX(d.SUB_ACCOUNT_ARB_NAME) snm, TO_CHAR(MIN(d.VM_DATE),'YYYYMM') ym, SUM(d.DR_AMOUNT-d.CR_AMOUNT) net, SUM(CASE WHEN SUM(d.DR_AMOUNT-d.CR_AMOUNT)>0 THEN SUM(d.DR_AMOUNT-d.CR_AMOUNT) ELSE 0 END) OVER (PARTITION BY d.VOUCHER_NO) pos, SUM(CASE WHEN SUM(d.DR_AMOUNT-d.CR_AMOUNT)<0 THEN SUM(d.DR_AMOUNT-d.CR_AMOUNT) ELSE 0 END) OVER (PARTITION BY d.VOUCHER_NO) neg FROM GL_TRANSACTIONS_DETAILS d WHERE d.STATUS<>'C' AND d.ACCOUNT_NO NOT LIKE '121%' AND d.ACCOUNT_NO NOT LIKE '122%' AND d.VOUCHER_NO IN (SELECT c.VOUCHER_NO FROM GL_TRANSACTIONS_DETAILS c WHERE c.STATUS<>'C' AND (c.ACCOUNT_NO LIKE '121%' OR c.ACCOUNT_NO LIKE '122%')) GROUP BY d.VOUCHER_NO, d.ACCOUNT_NO, NVL(d.SUB_ACCOUNT_NO,'-')) l JOIN (SELECT c.VOUCHER_NO, SUM(c.DR_AMOUNT-c.CR_AMOUNT) c FROM GL_TRANSACTIONS_DETAILS c WHERE c.STATUS<>'C' AND (c.ACCOUNT_NO LIKE '121%' OR c.ACCOUNT_NO LIKE '122%') GROUP BY c.VOUCHER_NO) x ON x.VOUCHER_NO=l.VOUCHER_NO WHERE l.ACCOUNT_NO LIKE '1240%') GROUP BY a, sub, ym HAVING ABS(SUM(alloc))>=0.005) GROUP BY a, sub;

-- 4) ncv — every line of vouchers with NO cash that touch investing/financing accounts (the non-cash transactions)
SELECT bkt, COUNT(*) n, LISTAGG(r,'~') WITHIN GROUP (ORDER BY r) r FROM (SELECT MOD(ROWNUM,80) bkt, v||'|'||dt||'|'||a||'|'||net r FROM (SELECT d.VOUCHER_NO v, TO_CHAR(MIN(d.VM_DATE),'YYYY-MM-DD') dt, d.ACCOUNT_NO a, ROUND(SUM(d.DR_AMOUNT-d.CR_AMOUNT),2) net FROM GL_TRANSACTIONS_DETAILS d WHERE d.STATUS<>'C' AND d.VM_DATE>=DATE '2019-01-01' AND d.VM_DATE<DATE '{D1}' AND d.VOUCHER_NO<>'JV1-24/04043' AND NOT EXISTS (SELECT 'X' FROM FINANCIAL_YEARS f WHERE f.GL_VOUCHER_NO=d.VOUCHER_NO) AND d.VOUCHER_NO IN (SELECT e.VOUCHER_NO FROM GL_TRANSACTIONS_DETAILS e WHERE e.STATUS<>'C' AND (e.ACCOUNT_NO LIKE '1110%' OR e.ACCOUNT_NO LIKE '1120%' OR e.ACCOUNT_NO LIKE '113%' OR e.ACCOUNT_NO IN ('4300008','3380000','1410000','1262000') OR e.ACCOUNT_NO LIKE '2112%' OR e.ACCOUNT_NO LIKE '2113%' OR e.ACCOUNT_NO LIKE '2125%' OR e.ACCOUNT_NO LIKE '2128%' OR e.ACCOUNT_NO LIKE '221%' OR e.ACCOUNT_NO LIKE '222%' OR e.ACCOUNT_NO LIKE '223%')) AND d.VOUCHER_NO NOT IN (SELECT c.VOUCHER_NO FROM GL_TRANSACTIONS_DETAILS c WHERE c.STATUS<>'C' AND (c.ACCOUNT_NO LIKE '121%' OR c.ACCOUNT_NO LIKE '122%')) GROUP BY d.VOUCHER_NO, d.ACCOUNT_NO HAVING ABS(SUM(d.DR_AMOUNT-d.CR_AMOUNT))>=0.005)) GROUP BY bkt;

-- 5) vch — voucher drill: allocations of SAR 20,000+ per voucher x account
SELECT bkt, COUNT(*) n, LISTAGG(r,'~') WITHIN GROUP (ORDER BY r) r FROM (SELECT MOD(ROWNUM,700) bkt, v||'|'||dt||'|'||a||'|'||ROUND(alloc,2) r FROM (SELECT l.VOUCHER_NO v, l.ACCOUNT_NO a, l.ym, l.dt, CASE WHEN l.f=1 THEN -l.net WHEN (x.c-l.fin)<0 AND l.net>0 AND l.pos>0 THEN (x.c-l.fin)*l.net/l.pos WHEN (x.c-l.fin)>0 AND l.net<0 AND l.neg<0 THEN (x.c-l.fin)*l.net/l.neg ELSE 0 END alloc FROM (SELECT d.VOUCHER_NO, d.ACCOUNT_NO, TO_CHAR(MIN(d.VM_DATE),'YYYYMM') ym, TO_CHAR(MIN(d.VM_DATE),'YYYY-MM-DD') dt, CASE WHEN (d.ACCOUNT_NO LIKE '2112%' OR d.ACCOUNT_NO LIKE '2113%' OR d.ACCOUNT_NO LIKE '2125%' OR d.ACCOUNT_NO LIKE '2128%' OR d.ACCOUNT_NO LIKE '221%' OR d.ACCOUNT_NO LIKE '222%' OR d.ACCOUNT_NO LIKE '223%' OR d.ACCOUNT_NO IN ('1262000','3290001')) THEN 1 ELSE 0 END f, SUM(d.DR_AMOUNT-d.CR_AMOUNT) net, SUM(CASE WHEN (d.ACCOUNT_NO LIKE '2112%' OR d.ACCOUNT_NO LIKE '2113%' OR d.ACCOUNT_NO LIKE '2125%' OR d.ACCOUNT_NO LIKE '2128%' OR d.ACCOUNT_NO LIKE '221%' OR d.ACCOUNT_NO LIKE '222%' OR d.ACCOUNT_NO LIKE '223%' OR d.ACCOUNT_NO IN ('1262000','3290001')) THEN -SUM(d.DR_AMOUNT-d.CR_AMOUNT) ELSE 0 END) OVER (PARTITION BY d.VOUCHER_NO) fin, SUM(CASE WHEN NOT (d.ACCOUNT_NO LIKE '2112%' OR d.ACCOUNT_NO LIKE '2113%' OR d.ACCOUNT_NO LIKE '2125%' OR d.ACCOUNT_NO LIKE '2128%' OR d.ACCOUNT_NO LIKE '221%' OR d.ACCOUNT_NO LIKE '222%' OR d.ACCOUNT_NO LIKE '223%' OR d.ACCOUNT_NO IN ('1262000','3290001')) AND SUM(d.DR_AMOUNT-d.CR_AMOUNT)>0 THEN SUM(d.DR_AMOUNT-d.CR_AMOUNT) ELSE 0 END) OVER (PARTITION BY d.VOUCHER_NO) pos, SUM(CASE WHEN NOT (d.ACCOUNT_NO LIKE '2112%' OR d.ACCOUNT_NO LIKE '2113%' OR d.ACCOUNT_NO LIKE '2125%' OR d.ACCOUNT_NO LIKE '2128%' OR d.ACCOUNT_NO LIKE '221%' OR d.ACCOUNT_NO LIKE '222%' OR d.ACCOUNT_NO LIKE '223%' OR d.ACCOUNT_NO IN ('1262000','3290001')) AND SUM(d.DR_AMOUNT-d.CR_AMOUNT)<0 THEN SUM(d.DR_AMOUNT-d.CR_AMOUNT) ELSE 0 END) OVER (PARTITION BY d.VOUCHER_NO) neg FROM GL_TRANSACTIONS_DETAILS d WHERE d.STATUS<>'C' AND d.VM_DATE<DATE '{D1}' AND d.ACCOUNT_NO NOT LIKE '121%' AND d.ACCOUNT_NO NOT LIKE '122%' AND d.VOUCHER_NO IN (SELECT c.VOUCHER_NO FROM GL_TRANSACTIONS_DETAILS c WHERE c.STATUS<>'C' AND (c.ACCOUNT_NO LIKE '121%' OR c.ACCOUNT_NO LIKE '122%')) GROUP BY d.VOUCHER_NO, d.ACCOUNT_NO) l JOIN (SELECT c.VOUCHER_NO, SUM(c.DR_AMOUNT-c.CR_AMOUNT) c FROM GL_TRANSACTIONS_DETAILS c WHERE c.STATUS<>'C' AND c.VM_DATE<DATE '{D1}' AND (c.ACCOUNT_NO LIKE '121%' OR c.ACCOUNT_NO LIKE '122%') GROUP BY c.VOUCHER_NO) x ON x.VOUCHER_NO=l.VOUCHER_NO) WHERE ABS(alloc)>=20000) GROUP BY bkt;

-- 6) desc — voucher descriptions for the drill
SELECT bkt, LISTAGG(r,'~') WITHIN GROUP (ORDER BY r) r FROM (SELECT MOD(ROWNUM,500) bkt, v||'|'||ds r FROM (SELECT c.VOUCHER_NO v, REPLACE(REPLACE(REPLACE(REPLACE(SUBSTR(MAX(c.DESCRIPTION) KEEP (DENSE_RANK FIRST ORDER BY ABS(c.DR_AMOUNT-c.CR_AMOUNT) DESC),1,70),'|','/'),'~','-'),CHR(10),' '),CHR(13),' ') ds FROM GL_TRANSACTIONS_DETAILS c WHERE c.STATUS<>'C' AND c.VM_DATE<DATE '{D1}' AND (c.ACCOUNT_NO LIKE '121%' OR c.ACCOUNT_NO LIKE '122%') GROUP BY c.VOUCHER_NO HAVING MAX(ABS(c.DR_AMOUNT-c.CR_AMOUNT))>=15000)) GROUP BY bkt;

-- 7) mixed — cash vouchers whose investing/financing lines got less (or more) cash than their full amount: see dmv/README (query in session log, 29-Sep-2026)
